// Writes a generated block into a pull request description, between <!-- <name> --> and <!-- /<name> --> with the
// block's note on the line after the opening marker: replaces the block in place, else adds it at the bottom of the
// description. Every other byte of the body stays. Fenced code is skipped, so quoted markers stay text.
// Usage: node .github/scripts/pr-description-block.mjs <owner/repo> <pr-number> <block-name> <content.md>
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { isMain } from './main.mjs';

// The blocks sit at the bottom of the description in this order.
const BLOCKS = {
  'token-budget': { note: '<!-- Generated on every push by the token-budget workflow; do not edit. -->' },
  preview: { note: '<!-- Generated by the preview workflows; do not edit. -->' },
};
const ORDER = Object.keys(BLOCKS);

const USAGE = 'usage: node .github/scripts/pr-description-block.mjs <owner/repo> <pr-number> <block-name> <content.md>';
const TRIES = 3;

const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Fenced code blocks are blanked, line ends kept, so searches keep the body's offsets and skip quoted markers. An unclosed fence runs to the end, as in CommonMark.
function unfenced(body) {
  return body.replace(/^ {0,3}((`|~)\2{2,})[^\r\n]*\r?\n[\s\S]*?(?:^ {0,3}\1\2*[ \t]*\r?$|(?![\s\S]))/gm, (fence) =>
    fence.replace(/[^\r\n]/g, ' '),
  );
}

// The block starts with the marker and the note on whole lines: a description may name a marker in its text.
function find(text, name) {
  const { note } = BLOCKS[name];
  return new RegExp(`^<!-- ${escape(name)} -->\\r?\\n${escape(note)}(?=\\r?$)[\\s\\S]*?^<!-- /${escape(name)} -->(?=\\r?$)`, 'm').exec(text);
}

export function withBlock(body, name, content) {
  const spec = BLOCKS[name];
  if (!spec) throw new Error(`unknown block "${name}"; known: ${ORDER.join(', ')}`);
  // A description edited in the browser has CRLF line ends: the block takes the body's.
  const eol = body.includes('\r\n') ? '\r\n' : '\n';
  const block = [`<!-- ${name} -->`, spec.note, ...content.replace(/\r?\n$/, '').split(/\r?\n/), `<!-- /${name} -->`].join(eol);
  const text = unfenced(body);
  const old = find(text, name);
  if (old) return body.slice(0, old.index) + block + body.slice(old.index + old[0].length);
  const at = bottom(body, text, name);
  if (at < body.length) return body.slice(0, at) + block + eol + eol + body.slice(at);
  return body === '' ? block + eol : body + (body.endsWith(eol + eol) ? '' : body.endsWith(eol) ? eol : eol + eol) + block + eol;
}

// A missing block goes at the end of the description, before the blocks that end it and follow it in ORDER.
// Fenced code at the end is text, so the end is measured on the body.
function bottom(body, text, name) {
  let at = body.length;
  for (;;) {
    const end = body.slice(0, at).trimEnd().length;
    const last = ORDER.map((n) => [n, find(text, n)]).find(([, m]) => m && m.index + m[0].length === end);
    if (!last || ORDER.indexOf(last[0]) < ORDER.indexOf(name)) return at;
    at = last[1].index;
  }
}

// Writes the block, then reads the description again: another workflow may have written an older body in between.
// Writes again while the block is missing or stale, and throws after `tries` writes.
export async function publish({ read, write, name, content, tries = TRIES }) {
  let body = await read();
  for (let attempt = 1; attempt <= tries; attempt++) {
    await write(withBlock(body, name, content));
    body = await read();
    if (withBlock(body, name, content) === body) return attempt;
  }
  throw new Error(`the ${name} block is still missing or stale after ${tries} writes: another writer keeps replacing the description`);
}

if (isMain(import.meta.url)) {
  const [repo, pr, name, file] = process.argv.slice(2);
  if (!file || !BLOCKS[name]) {
    console.error(USAGE);
    process.exit(2);
  }
  const gh = (args, input) => execFileSync('gh', [...args, pr, '--repo', repo], { encoding: 'utf8', input });
  try {
    await publish({
      read: () => JSON.parse(gh(['pr', 'view', '--json', 'body'])).body ?? '',
      write: (body) => gh(['pr', 'edit', '--body-file', '-'], body),
      name,
      content: readFileSync(file, 'utf8'),
    });
  } catch (error) {
    console.error(`::error::${error.message}`);
    process.exit(1);
  }
}
